WFJ.Data.add("book", {
  ["27188a14c98b8c17"] = { "15日目\n我らの献身が実を結んだ。wind stoneの建造を最初に終えたのは我らの野営地だ。ほかの愚か者どもが我らと一緒にいれば、一週間もかからずに終えられただろうに！\n\n明日、Baron Kazumその人を召喚する儀式を始める。彼は自らが最初にこの仕組みを試すと言い張り、我らは逆らえなかった。すぐに怒る方だからな。\n\nきっと我らにたいそう満足されることだろう。", "." },
  ["271b43dbef66b7c9"] = { "私は、血石が石英や黒曜石のような岩石の一種であるという前提から試験を始めた。そこで、一連の手順によって次のことを突き止めようとした。血石にどのような鉱物が含まれているか、その色と硬さを生むためにどのような力が加えられたか、そして岩石や鉱石に共通するその他の性質である。だが、苛立たしいことに、血石のペンダントは通常の鉱石のようには私の手順に反応しなかった。", "." },
  ["2728331127417a82"] = { "あなたの準備が整ったと知らせを受け、すぐにこの印章を送りました。Cenariusのドルイドは皆、我らの数が増えていくのを見て大いに満足しています。我らの存在が増したことで、精霊たちさえも力を増したように思えます。時と、いくらかの忍耐があれば、きっと我らの力はかつての偉大さを取り戻すでしょう。準備ができたら、Aldrassilの頂上近くで私を探してください。あなたがShadowglenにいる間は、私があなたの導き手となります。\n\n- ドルイドのトレーナー、Mardant Strongoak", "." },
  ["273b2dd8223a91a2"] = { "定命の社会の絶え間ない進出から逃れてきた強大なドラゴンたちは、Legionの闇の魔法を相手に互角以上には戦えずにいた。Aegwynnは悪魔たちに立ち向かい、高貴なドラゴンたちの助けを得て、彼らを根絶した。だが、最後の悪魔がこの定命の世界から追放された時、北の地全体に大嵐が巻き起こった。", "." },
  ["2742b90d3be34707"] = { "上質のwhitestone oak――乗っ取られる前、WestfallのMoonbrookの地下にある鉱山にはこの木材がたくさんあった。熱と圧力に強いため、より重要な格子や道具のいくつかを作るのに使われていたのだ。\n\nそれは海の向こうのどこかから船で運ばれた後、あの地下へ運び込まれた。君の武器を作るのに使えるほど十分に強い、珍しい木材だ。もし鉱山にまだ残っているなら、ゴブリンの木彫り職人たちが持っているだろう。", "." },
  ["27b66c097d40fe4c"] = { "Twilight's Hammerの全構成員に即時通達する。\n\n以下は、Abyssal Councilにおわす我らが主たちとの交信にwind stoneを用いる方法を記したものである。\n\nwind stoneをみだりに用いた者は、きわめて苦痛に満ちた方法で罰せられる。\n\n-Twilight Keeper Havunth", "." },
})
